package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Put a person on hold, or take them off it again. While held, their open (OPEN or PENDING) claims count in no live
 *  total; their SETTLED claims still do. */
public class HoldPerson {
    public void hold(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            ServerHttpConnection connection, PersonRepository repository, Audit audit, Rollup rollup,
            Out<Person> person) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        Person found = repository.find(id, pid);
        if (found == null) {
            throw new BadRequestException("no such person");
        }
        Rollup.Snapshot before = rollup.take(id);
        boolean held = !found.held();
        repository.hold(id, pid, held);
        audit.record((held ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + id + " by=" + by + " name=" + found.name());
        rollup.record(id, by, before);
        person.set(repository.find(id, pid));
    }
}
# Put a person on hold, or take them off it again (a toggle).
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
-- Whether a person is on hold: while held, their OPEN claims count in no live total (their SETTLED
-- claims still do).
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { peopleKey, usePeople, type Person } from '../people/usePeople';

/** A person's hold: whether they are on hold, and a button that puts them on hold or takes them off
 *  it again. While held, their open (OPEN or PENDING) claims count in no live total; their SETTLED claims still do. */
function PersonHold({ sheetId, personId }: { sheetId: string; personId: number }) {
  const people = usePeople(sheetId);
  const queryClient = useQueryClient();
  const p = people.data?.find((x) => x.id === personId);

  const toggle = useMutation({
    mutationFn: () => postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/hold`, {}),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
  });

  return (
    <>
      <td data-testid="person-hold">{p?.held ? 'yes' : 'no'}</td>
      <td>
        <button
          type="button"
          data-testid="person-hold-toggle"
          disabled={toggle.isPending}
          onClick={() => {
            toggle.reset();
            toggle.mutate();
          }}
        >
          {p?.held ? 'Release' : 'Hold'}
        </button>
        {toggle.isError && <span data-testid="person-error">{toggle.error.message}</span>}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHead.fill({
    order: 45,
    Component: () => (
      <>
        <th>Held</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 45, Component: PersonHold }),
];
