package net.officefloor.hq.app.person;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.BadRequestException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

@Repository
public class PersonRepository {

    /** The grade in force on the sheet's today: the one with the latest from-date on or before it. */
    private static final String GRADE_TODAY = "(SELECT g.grade FROM person_grade g WHERE g.person_id = person.id"
            + " AND (g.from_date IS NULL OR g.from_date <= (SELECT s.today FROM sheet s WHERE s.id = person.sheet_id))"
            + " ORDER BY g.from_date DESC NULLS LAST LIMIT 1) AS grade";

    private static final String COLUMNS = "id, name, " + GRADE_TODAY + ", version, statement_count, stated_total, statement_date, retired_from, held";

    private static final RowMapper<Person> ROW = (rs, i) -> new Person(rs.getLong("id"), rs.getString("name"),
            rs.getString("grade"), rs.getLong("version"), rs.getLong("statement_count"), rs.getString("stated_total"),
            rs.getDate("statement_date") == null ? null : rs.getDate("statement_date").toLocalDate().toString(),
            rs.getDate("retired_from") == null ? null : rs.getDate("retired_from").toLocalDate().toString(),
            rs.getBoolean("held"), List.of());

    private final JdbcTemplate jdbc;

    public PersonRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public boolean sheetExists(String sheetId) {
        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, sheetId);
        return known != null && known > 0;
    }

    /** The sheet's people in the order they were added. */
    public List<Person> list(String sheetId) {
        List<Person> people = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? ORDER BY id", ROW, sheetId);
        Map<Long, List<GradeFrom>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, grade, from_date FROM person_grade WHERE sheet_id = ? ORDER BY from_date NULLS FIRST",
                rs -> {
                    grades.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(gradeFrom(rs));
                }, sheetId);
        return people.stream().map(p -> p.withGrades(grades.getOrDefault(p.id(), List.of()))).toList();
    }

    private static GradeFrom gradeFrom(java.sql.ResultSet rs) throws java.sql.SQLException {
        return new GradeFrom(rs.getString("grade"),
                rs.getDate("from_date") == null ? null : rs.getDate("from_date").toLocalDate().toString());
    }

    /** A person's grades, oldest first. */
    public List<GradeFrom> grades(String sheetId, long id) {
        return jdbc.query("SELECT grade, from_date FROM person_grade WHERE sheet_id = ? AND person_id = ?"
                + " ORDER BY from_date NULLS FIRST", (rs, i) -> gradeFrom(rs), sheetId, id);
    }

    /** Give a person a grade from a from-date (null: from the beginning of time), replacing the one
     *  they had from that date. */
    public void grade(String sheetId, long id, String grade, LocalDate from) {
        Date on = from == null ? null : Date.valueOf(from);
        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date IS NOT DISTINCT FROM ?",
                sheetId, id, on);
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date) VALUES (?, ?, ?, ?)",
                sheetId, id, grade, on);
    }

    /** A person on the sheet; null when the sheet has no such person. */
    public Person find(String sheetId, long id) {
        List<Person> found = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ?", ROW,
                sheetId, id);
        return found.isEmpty() ? null : found.get(0).withGrades(grades(sheetId, id));
    }

    /** Record a statement taken of a person: one more, with its due-total and date. */
    public void stated(String sheetId, long id, String total, LocalDate date) {
        jdbc.update("UPDATE person SET statement_count = statement_count + 1, stated_total = ?, statement_date = ?"
                + " WHERE id = ? AND sheet_id = ?", total, Date.valueOf(date), id, sheetId);
    }

    /** Retire a person from a date. */
    public void retire(String sheetId, long id, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE id = ? AND sheet_id = ?", Date.valueOf(from), id, sheetId);
    }

    /** Put a person on hold, or take them off it. */
    public void hold(String sheetId, long id, boolean held) {
        jdbc.update("UPDATE person SET held = ? WHERE id = ? AND sheet_id = ?", held, id, sheetId);
    }

    /** The ids of the sheet's people who are on hold. */
    public Set<Long> heldIds(String sheetId) {
        return new HashSet<>(jdbc.queryForList("SELECT id FROM person WHERE sheet_id = ? AND held", Long.class, sheetId));
    }

    /** Refuse a claim of the person dated after the date they are retired from. */
    public void claimAllowed(String sheetId, long id, LocalDate date) throws BadRequestException {
        Person p = find(sheetId, id);
        if (p != null && p.retiredFrom() != null && date.isAfter(LocalDate.parse(p.retiredFrom()))) {
            throw new BadRequestException(p.name() + " is retired from " + p.retiredFrom());
        }
    }

    /** Whether another person on the sheet (other than {@code exceptId}; 0 for none) already has this name, ignoring case. */
    public boolean nameTaken(String sheetId, String name, long exceptId) {
        Integer taken = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND LOWER(name) = LOWER(?) AND id <> ?",
                Integer.class, sheetId, name, exceptId);
        return taken != null && taken > 0;
    }

    /** The person on the sheet with this name, ignoring case; null when there is none. */
    public Person findByName(String sheetId, String name) {
        List<Person> found = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND LOWER(name) = LOWER(?)",
                ROW, sheetId, name);
        return found.isEmpty() ? null : found.get(0);
    }

    public Person add(String sheetId, String name, String grade) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(c -> {
            PreparedStatement ps = c.prepareStatement(
                    "INSERT INTO person (sheet_id, name, grade) VALUES (?, ?, ?)", new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setString(3, grade);
            return ps;
        }, keys);
        long id = keys.getKey().longValue();
        grade(sheetId, id, grade, null);
        return new Person(id, name, grade, 1, 0, null, null, null, false, List.of(new GradeFrom(grade, null)));
    }

    /** Whether the sheet has this person. */
    public boolean exists(String sheetId, long id) {
        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM person WHERE id = ? AND sheet_id = ?",
                Integer.class, id, sheetId);
        return known != null && known > 0;
    }

    /** Change a person's name, if they are still at {@code version}, moving them to the next version;
     *  false when the sheet has no such person at that version. Their grades are given by {@link #grade}. */
    public boolean update(String sheetId, long id, long version, String name) {
        return jdbc.update(
                "UPDATE person SET name = ?, version = version + 1 WHERE id = ? AND sheet_id = ? AND version = ?",
                name, id, sheetId, version) > 0;
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/** The sheet's figures as shown: each person's claimed and due-total, and the sheet's claimed-total and
 *  due-total. A change takes them before it writes, then after its own audit lines records one ROLLUP
 *  line per person whose figures moved (people in the order they were added; a new person counts as
 *  moved), then a TOTALS line when the sheet's totals moved. */
@Service
public class Rollup {

    /** A person's figures: claimed (two decimals) and due-total (two decimals, or 'n/a'). */
    record Figures(String name, String claimed, String dueTotal) {
        boolean same(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal);
        }
    }

    /** The figures of a sheet at one moment, people by id in the order they were added. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final SheetRepository sheets;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures now. A person's due-total is the sum of their counting claims' dues now (late charges included),
     *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
     *  then and no counting claim keeps a fixed figure or has a due (at the grade it was claimed under). The sheet's due-total skips 'n/a'. */
    public Snapshot take(String sheetId) {
        List<Person> everyone = people.list(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        if (!everyone.isEmpty()) {
            LocalDate today = sheets.today(sheetId);
            List<Claim> all = claims.list(sheetId);
            for (Person p : everyone) {
                BigDecimal claimed = BigDecimal.ZERO.setScale(2);
                BigDecimal due = BigDecimal.ZERO.setScale(2);
                boolean fixed = false;
                for (Claim c : all) {
                    if (c.personId() != p.id() || !c.counts(p.held())) continue;
                    claimed = claimed.add(new BigDecimal(c.amount()));
                    fixed |= c.fixed();
                    BigDecimal now = claims.dueNow(sheetId, c);
                    if (now != null) due = due.add(now);
                    fixed |= now != null;
                }
                boolean shown = fixed || claims.rated(sheetId, p.id(), today);
                figures.put(p.id(), new Figures(p.name(), claimed.toPlainString(),
                        shown ? due.toPlainString() : "n/a"));
                claimedTotal = claimedTotal.add(claimed);
                if (shown) dueTotal = dueTotal.add(due);
            }
        }
        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString());
    }

    /** Record the lines for whatever figures moved since {@code before}. */
    public void record(String sheetId, String by, Snapshot before) {
        Snapshot after = take(sheetId);
        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
            Figures now = e.getValue();
            if (now.same(before.people().get(e.getKey()))) continue;
            audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
                    + now.claimed() + " due-total=" + now.dueTotal());
        }
        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())) {
            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal());
        }
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Take a person's statement: record their due-total now, and bind each claim of theirs that counts (a
 *  held person's open (OPEN or PENDING) claims do not) to the figure it has now (a settled claim keeps its frozen due); a
 *  claim that does not count is unbound (live again). A late charge is never bound: it keeps following
 *  the sheet's today. The due-total is as shown: the sum of the counting claims' dues now (late charges
 *  included), skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today
 *  is in force then and no counting claim has a fixed figure or a due (at the grade it was claimed under). */
public class TakeStatement {
    public void take(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            ServerHttpConnection connection, PersonRepository people, ClaimRepository claims,
            SheetRepository sheets, Audit audit, Rollup rollup, Out<Person> person) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        Person found = people.find(id, pid);
        if (found == null) {
            throw new BadRequestException("no such person");
        }
        LocalDate today = sheets.today(id);
        Rollup.Snapshot before = rollup.take(id);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean fixed = false;
        int count = 0;
        for (Claim c : claims.ofPerson(id, pid)) {
            if (!c.counts(found.held())) {
                claims.bind(id, c.id(), false, null);
                continue;
            }
            count++;
            fixed |= c.fixed();
            // The claim is bound to its figure; its late charge is not bound, but counts in the due-total.
            BigDecimal figure = claims.figure(id, c);
            BigDecimal now = claims.dueNow(id, c);
            if (now != null) {
                total = total.add(now);
                fixed = true;
            }
            claims.bind(id, c.id(), true, figure);
        }
        String dueTotal = fixed || claims.rated(id, pid, today) ? total.setScale(2).toPlainString() : "n/a";
        people.stated(id, pid, dueTotal, today);
        audit.record("STATEMENT sheet=" + id + " by=" + by + " name=" + found.name() + " due-total=" + dueTotal
                + " claims=" + count);
        rollup.record(id, by, before);
        person.set(people.find(id, pid));
    }
}
